import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/**
 * Thrown by `assertWorkspaceWritable()` when a workspace's subscription is not
 * in good standing. Mapped to `plan_limit_exceeded` by `toAppError()`.
 */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is locked (${reason})`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * The pure lock rule, evaluated against the subscription as stored at `now`.
 *
 * No subscription, or an active one, is writable. `past_due` locks
 * immediately. `trialing` locks once the current period end is reached.
 * `canceled` locks once its cancellation date is reached — a cancellation
 * scheduled for later keeps the workspace writable until then, and a
 * canceled subscription with no cancellation date counts as canceled now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return now >= new Date(subscription.currentPeriodEnd)
        ? "trial_ended"
        : null;
    case "canceled": {
      const { cancelAt } = subscription;
      if (cancelAt === null) return "canceled";
      return now >= new Date(cancelAt) ? "canceled" : null;
    }
  }
}

