import { describe, expect, it } from "vitest";
import { lockReasonFor } from "@/lib/billing-lock";
import type { Subscription } from "@/types/billing";
import { toIsoTimestamp } from "@/types/common";

function sub(overrides: Partial<Subscription>): Subscription {
  return {
    id: "s1" as any,
    orgId: "o1" as any,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 1,
    currentPeriodStart: toIsoTimestamp(new Date("2026-01-01")),
    currentPeriodEnd: toIsoTimestamp(new Date("2026-02-01")),
    cancelAt: null,
    createdAt: toIsoTimestamp(new Date("2026-01-01")),
    updatedAt: toIsoTimestamp(new Date("2026-01-01")),
    ...overrides,
  };
}

describe("lockReasonFor", () => {
  it("null sub -> writable", () => {
    expect(lockReasonFor(null)).toBeNull();
  });
  it("active -> writable", () => {
    expect(lockReasonFor(sub({ status: "active" }))).toBeNull();
  });
  it("past_due -> locked", () => {
    expect(lockReasonFor(sub({ status: "past_due" }))).toBe("past_due");
  });
  it("trialing before period end -> writable", () => {
    const now = new Date("2026-01-15");
    expect(lockReasonFor(sub({ status: "trialing" }), now)).toBeNull();
  });
  it("trialing at/after period end -> trial_ended", () => {
    const now = new Date("2026-02-01");
    expect(lockReasonFor(sub({ status: "trialing" }), now)).toBe("trial_ended");
    const later = new Date("2026-02-02");
    expect(lockReasonFor(sub({ status: "trialing" }), later)).toBe("trial_ended");
  });
  it("canceled with future cancelAt -> writable until then", () => {
    const cancelAt = toIsoTimestamp(new Date("2026-03-01"));
    const now = new Date("2026-02-15");
    expect(lockReasonFor(sub({ status: "canceled", cancelAt }), now)).toBeNull();
  });
  it("canceled at/after cancelAt -> canceled", () => {
    const cancelAt = toIsoTimestamp(new Date("2026-03-01"));
    expect(lockReasonFor(sub({ status: "canceled", cancelAt }), new Date("2026-03-01"))).toBe("canceled");
    expect(lockReasonFor(sub({ status: "canceled", cancelAt }), new Date("2026-03-02"))).toBe("canceled");
  });
  it("canceled with no cancelAt -> canceled now", () => {
    expect(lockReasonFor(sub({ status: "canceled", cancelAt: null }))).toBe("canceled");
  });
});
EOF
