import { afterAll, beforeAll, describe, expect, it } from "vitest";

vi_import();
function vi_import() {}

import { getDb, subscriptions } from "@/server/db";
import { eq } from "drizzle-orm";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { WorkspaceLockedError } from "@/lib/billing-lock";
import { createTenant, useTemporaryDatabase, issueInput } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("workspace lock integration", () => {
  it("refuses issue creation when past_due, but permission errors still win", async () => {
    const tenant = await createTenant("lock-int", "growth");
    getDb().update(subscriptions).set({ status: "past_due" }).where(eq(subscriptions.orgId, tenant.org.id)).run();

    await expect(
      issueService.createIssue(tenant.actors.viewer, issueInput(tenant.org.id, tenant.project.id)),
    ).rejects.toBeInstanceOf(Object); // viewer lacks permission - should be PermissionDeniedError not lock error
    try {
      await issueService.createIssue(tenant.actors.viewer, issueInput(tenant.org.id, tenant.project.id));
    } catch (e) {
      expect(e).not.toBeInstanceOf(WorkspaceLockedError);
    }

    await expect(
      issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id)),
    ).rejects.toBeInstanceOf(WorkspaceLockedError);
  });

  it("member removal is refused while locked", async () => {
    const tenant = await createTenant("lock-int2", "growth");
    getDb().update(subscriptions).set({ status: "past_due" }).where(eq(subscriptions.orgId, tenant.org.id)).run();

    const memberRepo = await import("@/server/repositories/member-repository");
    const memberRow = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!memberRow) throw new Error("expected member row");

    await expect(
      memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: memberRow.id }),
    ).rejects.toBeInstanceOf(WorkspaceLockedError);
  });
});
